from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # The full color-2 line is a stop boundary. Move the non-background
    # pattern next to it, and mark the row/column just behind the pattern.
    sep_row = next((r for r in range(h) if all(v == 2 for v in grid[r])), None)
    sep_col = next((c for c in range(w) if all(grid[r][c] == 2 for r in range(h))), None)

    cells = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
             if grid[r][c] != bg and grid[r][c] != 2]
    if not cells:
        return out

    if sep_row is not None:
        min_r = min(r for r, _, _ in cells)
        max_r = max(r for r, _, _ in cells)
        if max_r < sep_row:
            dr = (sep_row - 1) - max_r
            stripe = min_r + dr - 1
        elif min_r > sep_row:
            dr = (sep_row + 1) - min_r
            stripe = max_r + dr + 1
        else:
            return out
        for r, c, _ in cells:
            out[r][c] = bg
        for r in range(w):
            if 0 <= stripe < h:
                out[stripe][r] = 8
        for r, c, color in cells:
            nr = r + dr
            if 0 <= nr < h:
                out[nr][c] = color
        return out

    if sep_col is not None:
        min_c = min(c for _, c, _ in cells)
        max_c = max(c for _, c, _ in cells)
        if max_c < sep_col:
            dc = (sep_col - 1) - max_c
            stripe = min_c + dc - 1
        elif min_c > sep_col:
            dc = (sep_col + 1) - min_c
            stripe = max_c + dc + 1
        else:
            return out
        for r, c, _ in cells:
            out[r][c] = bg
        if 0 <= stripe < w:
            for r in range(h):
                out[r][stripe] = 8
        for r, c, color in cells:
            nc = c + dc
            if 0 <= nc < w:
                out[r][nc] = color
    return out


